<?php
declare(strict_types=1); namespace App\DataGrid\Repository; use App\DataGrid\Configuration\GridDefinition; use App\Entity\User; use Doctrine\ORM\QueryBuilder; use Symfony\Bundle\SecurityBundle\Security; final class UserDataTableRepository extends AbstractDataTableRepository {protected function rootAlias():string{return'u';} protected function configureQueryBuilder(QueryBuilder $q,GridDefinition $d,Security $s):void{$q->andWhere('u.deletedAt IS NULL');} protected function configureSelect(QueryBuilder $q,GridDefinition $d,Security $s):void{$q->select('u');} protected function serializeRow(object $e,GridDefinition $d,Security $s):array{$u=$e;if(!$u instanceof User)throw new \LogicException();$v=['id'=>$u->getId(),'email'=>$u->getEmail(),'firstName'=>$u->getFirstName(),'lastName'=>$u->getLastName(),'fullName'=>$u->getFullName(),'isActive'=>$u->isActive(),'roles'=>$u->getRoles(),'createdAt'=>$u->getCreatedAt()->format(DATE_ATOM),'updatedAt'=>$u->getUpdatedAt()->format(DATE_ATOM)];return array_intersect_key($v,$d->columns);}}
